import { useMemo, useState } from 'react';
import { useApp } from '../store/AppStore';
import type { ParseResult, Txn } from '../types';
import { parseCSV, parseSMS, parseStatementText } from '../domain/parse';
import { categorize } from '../domain/categorize';
import { CATEGORIES, CATEGORY_MAP } from '../data/categories';
import { SAMPLE_CSV, SAMPLE_SMS } from '../data/seed';
import { money } from '../lib/format';
import { monthLabel } from '../lib/date';
import { navigate } from '../lib/router';
import { Icon } from '../components/Icon';
import { Empty, Modal, Tabs, useToast } from '../components/ui';
import { downloadFile } from '../lib/export';

type Tab = 'csv' | 'pdf' | 'sms';

export default function Inbox() {
  const { state, importRows, approveBatch, discardBatch, updateTxn, deleteTxns, correctCategory } = useApp();
  const { push } = useToast();

  const [tab, setTab] = useState<Tab>('csv');
  const [dragging, setDragging] = useState(false);
  const [busy, setBusy] = useState(false);
  const [preview, setPreview] = useState<ParseResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [smsText, setSmsText] = useState('');
  const [pasteText, setPasteText] = useState('');
  const [showPaste, setShowPaste] = useState(false);
  const [batchFilter, setBatchFilter] = useState<string | null>(null);

  const pending = state.txns.filter((t) => t.pending);
  const pendingShown = batchFilter ? pending.filter((t) => t.batchId === batchFilter) : pending;

  const previewRows = useMemo(() => {
    if (!preview) return [];
    return preview.rows.map((r) => ({ ...r, cat: categorize(r.description, r.amount, state.rules) }));
  }, [preview, state.rules]);

  const reset = () => {
    setPreview(null);
    setError(null);
  };

  const parsePdf = async (file: File) => {
    const pdfjs: any = await import('pdfjs-dist');
    const worker = await import('pdfjs-dist/build/pdf.worker.min.mjs?url');
    pdfjs.GlobalWorkerOptions.workerSrc = (worker as { default: string }).default;
    const buf = await file.arrayBuffer();
    const doc = await pdfjs.getDocument({ data: new Uint8Array(buf) }).promise;
    let text = '';
    for (let i = 1; i <= doc.numPages; i++) {
      const page = await doc.getPage(i);
      const content = await page.getTextContent();
      let lastY: number | null = null;
      for (const item of content.items as any[]) {
        if (!('str' in item)) continue;
        const y = item.transform?.[5] ?? null;
        if (lastY !== null && y !== null && Math.abs(y - lastY) > 3) text += '\n';
        text += item.str;
        if (item.hasEOL) text += '\n';
        else text += ' ';
        lastY = y;
      }
      text += '\n';
    }
    if (!text.trim()) throw new Error('No text layer found. The PDF may be scanned.');
    return parseStatementText(text, file.name);
  };

  const handleFile = async (file: File) => {
    reset();
    setBusy(true);
    try {
      if (/\.pdf$/i.test(file.name)) {
        const result = await parsePdf(file);
        setPreview(result);
        setTab('pdf');
      } else {
        const text = await file.text();
        if (/\.(csv|tsv)$/i.test(file.name) || text.includes(',')) {
          setPreview(parseCSV(text, file.name));
          setTab('csv');
        } else {
          setPreview(parseSMS(text, file.name));
          setTab('sms');
        }
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'The file could not be read.');
    } finally {
      setBusy(false);
    }
  };

  const loadSample = async () => {
    reset();
    setBusy(true);
    try {
      if (tab === 'csv') {
        setPreview(parseCSV(SAMPLE_CSV, 'hdfc-october-sample.csv'));
      } else if (tab === 'sms') {
        setSmsText(SAMPLE_SMS);
        setPreview(parseSMS(SAMPLE_SMS, 'bank-alerts.txt'));
      } else {
        const url = `${import.meta.env.BASE_URL}samples/baseline-statement.pdf`;
        const res = await fetch(url);
        if (!res.ok) throw new Error('Sample PDF is missing. Paste statement text below instead.');
        const blob = await res.blob();
        const file = new File([blob], 'sample-statement.pdf', { type: 'application/pdf' });
        setPreview(await parsePdf(file));
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Could not load the sample.');
    } finally {
      setBusy(false);
    }
  };

  const commit = (approve: boolean) => {
    if (!preview) return;
    const summary = importRows(preview.rows, preview.meta.source, preview.meta.fileName);
    if (approve) approveBatch(summary.batchId);
    if (summary.added > 0) {
      push(
        `${summary.added} added${summary.duplicates ? `, ${summary.duplicates} duplicate${summary.duplicates > 1 ? 's' : ''} skipped` : ''}. ${approve ? 'Approved and modelled.' : 'Waiting in review.'}`,
        { label: 'Review', run: () => setBatchFilter(summary.batchId) }
      );
    } else {
      push('Every row in this file is already in the ledger.');
    }
    reset();
  };

  return (
    <div className="page">
      <div className="page-head">
        <div>
          <div className="eyebrow">Ingestion · nothing leaves your browser</div>
          <h1 className="display">Bring the mess. <em>Leave with a model.</em></h1>
          <p className="lede">
            Bank CSVs with warning rows, PDF statements, and a dozen different SMS formats. Parsing happens locally;
            nothing is uploaded anywhere.
          </p>
        </div>
        <div className="head-actions">
          <button className="btn btn-ghost" onClick={() => navigate('/transactions?q=')}>
            <Icon name="receipt" size={14} /> Open the ledger
          </button>
        </div>
      </div>

      <div className="grid">
        <section className="panel col-8">
          <div className="panel-head" style={{ flexDirection: 'column', alignItems: 'stretch', gap: 8 }}>
            <div className="row-between">
              <div>
                <h2 className="panel-title">Import a statement</h2>
                <p className="panel-sub">Choose a format, then drop a file or use a sample.</p>
              </div>
              <span className="badge info"><Icon name="lock" size={10} /> Local only</span>
            </div>
            <Tabs
              tabs={[
                { id: 'csv', label: 'Bank CSV' },
                { id: 'pdf', label: 'PDF statement' },
                { id: 'sms', label: 'SMS alerts' },
              ]}
              value={tab}
              onChange={(t) => { setTab(t as Tab); reset(); }}
            />
          </div>

          <div className="panel-body">
            {tab !== 'sms' ? (
              <>
                <div
                  className={`dropzone ${dragging ? 'drag' : ''}`}
                  onDragOver={(e) => { e.preventDefault(); setDragging(true); }}
                  onDragLeave={() => setDragging(false)}
                  onDrop={(e) => {
                    e.preventDefault();
                    setDragging(false);
                    const file = e.dataTransfer.files?.[0];
                    if (file) void handleFile(file);
                  }}
                >
                  <Icon name={tab === 'csv' ? 'file' : 'upload'} size={20} style={{ margin: '0 auto', color: 'var(--muted)' }} />
                  <h3>{busy ? 'Reading…' : tab === 'csv' ? 'Drop a CSV or TSV statement' : 'Drop a PDF statement'}</h3>
                  <p>{tab === 'csv' ? 'Comma, semicolon, tab, or pipe separated. Headers are detected automatically.' : 'Text-based PDFs only. Scanned images need text extraction first.'}</p>
                  <div className="row" style={{ justifyContent: 'center', marginTop: 12 }}>
                    <label className="btn btn-sm">
                      Choose file
                      <input
                        type="file"
                        accept={tab === 'csv' ? '.csv,.tsv,.txt' : '.pdf'}
                        style={{ display: 'none' }}
                        onChange={(e) => { const f = e.target.files?.[0]; if (f) void handleFile(f); e.currentTarget.value = ''; }}
                      />
                    </label>
                    <button className="btn btn-sm" onClick={() => void loadSample()} disabled={busy}>
                      Use sample {tab === 'csv' ? 'CSV' : 'PDF'}
                    </button>
                  </div>
                </div>
                <div className="row-between" style={{ marginTop: 10 }}>
                  <span className="tiny" style={{ color: 'var(--muted)' }}>
                    {tab === 'csv' ? 'Sample includes a warning row, a footer row, and two duplicates.' : 'The sample PDF is a real text-layer statement.'}
                  </span>
                  <div className="row" style={{ gap: 10 }}>
                    {tab === 'pdf' && (
                      <button className="linkish small" onClick={() => setShowPaste((v) => !v)}>
                        {showPaste ? 'Hide text paste' : 'Paste statement text instead'}
                      </button>
                    )}
                    {tab === 'csv' && (
                      <button className="linkish small" onClick={() => downloadFile(SAMPLE_CSV, 'baseline-sample-statement.csv')}>
                        Download sample
                      </button>
                    )}
                  </div>
                </div>
                {tab === 'pdf' && showPaste && (
                  <div style={{ marginTop: 10 }}>
                    <textarea
                      className="textarea mono"
                      rows={6}
                      style={{ fontSize: 11.5 }}
                      placeholder={'04/10/2026  SWIGGY BANGALORE  486.00 DR  184320.50'}
                      value={pasteText}
                      onChange={(e) => setPasteText(e.target.value)}
                    />
                    <button
                      className="btn btn-sm btn-primary"
                      style={{ marginTop: 8 }}
                      disabled={!pasteText.trim()}
                      onClick={() => setPreview(parseStatementText(pasteText, 'pasted-statement.txt'))}
                    >
                      Parse pasted text
                    </button>
                  </div>
                )}
              </>
            ) : (
              <>
                <div className="field">
                  <label htmlFor="sms-box">Paste bank SMS alerts, one per line</label>
                  <textarea
                    id="sms-box"
                    className="textarea mono"
                    rows={7}
                    style={{ fontSize: 11.5 }}
                    placeholder={'HDFC Bank: Rs.486.00 debited from a/c XX4412 on 04-10-26 to SWIGGY.'}
                    value={smsText}
                    onChange={(e) => setSmsText(e.target.value)}
                  />
                </div>
                <div className="row" style={{ marginTop: 10 }}>
                  <button className="btn btn-primary" disabled={!smsText.trim()} onClick={() => setPreview(parseSMS(smsText, 'pasted-alerts.txt'))}>
                    <Icon name="spark" size={14} /> Parse alerts
                  </button>
                  <button className="btn" onClick={() => void loadSample()}>Use sample SMS</button>
                  <span className="tiny" style={{ color: 'var(--muted)' }}>Handles debited, credited, spent, and UPI phrasing.</span>
                </div>
              </>
            )}

            {error && (
              <div className="note guard" style={{ marginTop: 12, borderLeftColor: 'var(--negative)' }}>
                <strong>Could not read that file.</strong> {error}
              </div>
            )}
          </div>

          <div className="panel-foot">
            <span className="tiny" style={{ color: 'var(--muted)' }}>
              {state.txns.length} transactions already modelled · {state.batches.length} imports logged
            </span>
            <button className="linkish small" onClick={() => navigate('/rules')}>See what the model has learned</button>
          </div>
        </section>

        <aside className="panel col-4">
          <div className="panel-head">
            <div>
              <h2 className="panel-title">The pipeline</h2>
              <p className="panel-sub">What happens between file and model.</p>
            </div>
          </div>
          <div className="panel-body">
            <ol className="stack-sm">
              {[
                { n: '01', t: 'Detect the shape', d: 'Delimiter, header row, date format, debit vs credit columns.' },
                { n: '02', t: 'Clean each line', d: 'Amounts, references, and merchant names are normalised.' },
                { n: '03', t: 'Categorise with reasons', d: 'Known merchants score high. Everything else asks for a correction.' },
                { n: '04', t: 'Check for duplicates', d: 'A fingerprint of date, amount, and description prevents double counting.' },
              ].map((s) => (
                <li key={s.n} className="row" style={{ alignItems: 'flex-start', gap: 10 }}>
                  <span className="mono tiny" style={{ color: 'var(--accent)', paddingTop: 2 }}>{s.n}</span>
                  <span>
                    <span className="small strong">{s.t}</span>
                    <span className="small muted" style={{ display: 'block' }}>{s.d}</span>
                  </span>
                </li>
              ))}
            </ol>
            <div className="divider dashed" />
            <div className="row-between small">
              <span className="muted">Waiting for review</span>
              <span className="num">{pending.length}</span>
            </div>
            <div className="row-between small" style={{ marginTop: 4 }}>
              <span className="muted">Rules learned</span>
              <span className="num">{state.rules.filter((r) => r.source === 'learned').length}</span>
            </div>
            <div className="row-between small" style={{ marginTop: 4 }}>
              <span className="muted">Corrections recorded</span>
              <span className="num">{state.corrections.length}</span>
            </div>
          </div>
        </aside>

        {preview && (
          <section className="panel col-12" style={{ borderColor: 'var(--accent)' }}>
            <div className="panel-head">
              <div>
                <h2 className="panel-title">Preview · {preview.meta.fileName}</h2>
                <p className="panel-sub">
                  {preview.meta.detectedFormat} · {preview.rows.length} rows read
                  {preview.errors.length ? ` · ${preview.errors.length} line${preview.errors.length > 1 ? 's' : ''} skipped` : ''}
                </p>
              </div>
              <div className="row" style={{ gap: 8 }}>
                <button className="btn" onClick={reset}>Discard</button>
                <button className="btn" onClick={() => commit(false)}>Add to inbox</button>
                <button className="btn btn-primary" onClick={() => commit(true)}>
                  <Icon name="check" size={14} /> Add & approve {previewRows.length}
                </button>
              </div>
            </div>
            {preview.errors.length > 0 && (
              <div className="panel-body" style={{ paddingBottom: 0 }}>
                <div className="note guard" style={{ borderLeftColor: 'var(--accent)' }}>
                  <strong>Skipped lines:</strong> {preview.errors.slice(0, 2).join(' ')}
                  {preview.errors.length > 2 ? ` (+${preview.errors.length - 2} more)` : ''}
                </div>
              </div>
            )}
            <div className="panel-body flush" style={{ marginTop: 12 }}>
              <div className="table-wrap">
                <table className="tbl">
                  <thead>
                    <tr>
                      <th>Date</th>
                      <th>Description</th>
                      <th>Auto category</th>
                      <th>Confidence</th>
                      <th className="right">Amount</th>
                      <th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {previewRows.slice(0, 10).map((r, i) => (
                      <tr key={`${r.hash}-${i}`}>
                        <td className="mono small nowrap">{r.date}</td>
                        <td>
                          <div className="txn-merchant ellipsis" style={{ maxWidth: 330 }}>{r.description}</div>
                        </td>
                        <td>
                          <span className="row" style={{ gap: 6 }}>
                            <span className="cat-dot" style={{ background: CATEGORY_MAP[r.cat.category]?.color }} />
                            <span className="small">{CATEGORY_MAP[r.cat.category]?.name}</span>
                          </span>
                        </td>
                        <td>
                          <span className={`small ${r.cat.confidence > 0.85 ? 'pos' : r.cat.confidence > 0.5 ? '' : 'neg'}`}>
                            {Math.round(r.cat.confidence * 100)}%
                          </span>
                        </td>
                        <td className={`money ${r.amount > 0 ? 'pos' : ''}`}>
                          {r.amount > 0 ? '+' : '−'}{money(Math.abs(r.amount))}
                        </td>
                        <td>
                          {state.txns.some((t) => t.hash === r.hash)
                            ? <span className="badge warn">Duplicate</span>
                            : <span className="badge pos">New</span>}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {previewRows.length > 10 && (
                <p className="tiny" style={{ color: 'var(--muted)', padding: '10px 16px' }}>
                  Showing the first 10 of {previewRows.length} rows. All rows will be imported.
                </p>
              )}
            </div>
          </section>
        )}

        <section className="panel col-7">
          <div className="panel-head">
            <div>
              <h2 className="panel-title">Waiting for review</h2>
              <p className="panel-sub">
                {pendingShown.length} line{pendingShown.length === 1 ? '' : 's'} not yet counted in the model.
              </p>
            </div>
            <div className="row" style={{ gap: 6 }}>
              {batchFilter && (
                <button className="chip" onClick={() => setBatchFilter(null)}>
                  <Icon name="x" size={10} /> Clear batch filter
                </button>
              )}
              <button
                className="btn btn-sm"
                disabled={!pendingShown.length}
                onClick={() => {
                  pendingShown.forEach((t) => updateTxn(t.id, { pending: false }));
                  if (batchFilter) approveBatch(batchFilter);
                  push(`Approved ${pendingShown.length} transactions`);
                }}
              >
                Approve all
              </button>
            </div>
          </div>
          <div className="panel-body flush">
            {pendingShown.length === 0 ? (
              <Empty
                icon="check"
                title="The inbox is clear"
                body="Every imported line has been reviewed. New statements will queue up here before they touch the model."
              />
            ) : (
              <div className="table-wrap" style={{ maxHeight: 440, overflowY: 'auto' }}>
                <table className="tbl">
                  <thead>
                    <tr>
                      <th>Date</th>
                      <th>Merchant</th>
                      <th>Category</th>
                      <th className="right">Amount</th>
                      <th className="right">Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {pendingShown.slice(0, 40).map((t) => (
                      <tr key={t.id} className="pending">
                        <td className="mono small nowrap">{t.date.slice(5)}</td>
                        <td>
                          <div className="txn-merchant ellipsis" style={{ maxWidth: 170 }}>{t.merchant}</div>
                          <div className="tiny" style={{ color: 'var(--muted)' }}>{t.source.toUpperCase()} · {Math.round(t.confidence * 100)}%</div>
                        </td>
                        <td>
                          <select
                            className="select select-sm"
                            style={{ width: 130 }}
                            value={t.category}
                            aria-label={`Category for ${t.merchant}`}
                            onChange={(e) => correctCategory(t.id, e.target.value, false)}
                          >
                            {CATEGORIES.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
                          </select>
                        </td>
                        <td className={`money ${t.amount > 0 ? 'pos' : ''}`}>{t.amount > 0 ? '+' : '−'}{money(Math.abs(t.amount))}</td>
                        <td className="right">
                          <div className="row" style={{ gap: 2, justifyContent: 'flex-end' }}>
                            <button
                              className="btn btn-ghost btn-icon"
                              aria-label={`Approve ${t.merchant}`}
                              title="Approve"
                              onClick={() => { updateTxn(t.id, { pending: false }); push('Approved'); }}
                            >
                              <Icon name="check" size={13} />
                            </button>
                            <button
                              className="btn btn-ghost btn-icon"
                              aria-label={`Discard ${t.merchant}`}
                              title="Discard"
                              onClick={() => { deleteTxns([t.id]); push('Line discarded'); }}
                            >
                              <Icon name="trash" size={13} />
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </section>

        <section className="panel col-5">
          <div className="panel-head">
            <div>
              <h2 className="panel-title">Import history</h2>
              <p className="panel-sub">Every batch, and what it changed.</p>
            </div>
          </div>
          <div className="panel-body" style={{ paddingTop: 4 }}>
            {state.batches.slice(0, 6).map((b) => (
              <div key={b.id} className="goal-row">
                <div className="row-between" style={{ gap: 8 }}>
                  <span className="small strong ellipsis" style={{ maxWidth: 220 }}>{b.fileName}</span>
                  <span className={`badge ${b.approved ? 'pos' : 'warn'}`}>{b.approved ? 'Approved' : 'In review'}</span>
                </div>
                <div className="tiny" style={{ color: 'var(--muted)', marginTop: 3 }}>
                  {b.source.toUpperCase()} · {new Date(b.importedAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })} ·{' '}
                  {b.added} added{b.duplicates ? ` · ${b.duplicates} duplicates` : ''}
                </div>
                {!b.approved && b.added > 0 && (
                  <div className="row" style={{ gap: 6, marginTop: 6 }}>
                    <button className="btn btn-sm" onClick={() => { setBatchFilter(b.id); push('Showing that batch'); }}>Review</button>
                    <button className="btn btn-sm btn-ghost" onClick={() => { approveBatch(b.id); push('Batch approved'); }}>Approve batch</button>
                    <button
                      className="btn btn-sm btn-ghost btn-danger"
                      onClick={() => { discardBatch(b.id); push('Batch discarded'); }}
                    >
                      Discard
                    </button>
                  </div>
                )}
              </div>
            ))}
            {state.batches.length === 0 && <Empty icon="upload" title="No imports yet" body="Your first statement will show up here with a full audit trail." />}
          </div>
          <div className="panel-foot">
            <span className="tiny" style={{ color: 'var(--muted)' }}>
              Latest: {state.batches[0] ? monthLabel(String(new Date(state.batches[0].importedAt).toISOString().slice(0, 7))) : '—'}
            </span>
            <button className="linkish small" onClick={() => navigate('/settings')}>Export all data</button>
          </div>
        </section>
      </div>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { useApp } from '../store/AppStore';
import type { Rule } from '../types';
import { CATEGORIES, CATEGORY_MAP } from '../data/categories';
import { CATEGORY_MAP as CM } from '../data/categories';
import { money } from '../lib/format';
import { Icon } from '../components/Icon';
import { Confirm, Empty, Modal, Switch, useToast } from '../components/ui';
import { ruleMatches } from '../domain/categorize';

export default function Rules() {
  const { state, addRule, updateRule, deleteRule, applyRuleRetro } = useApp();
  const { push } = useToast();
  const [editing, setEditing] = useState<Rule | null>(null);
  const [creating, setCreating] = useState(false);
  const [testing, setTesting] = useState<Rule | null>(null);
  const [retro, setRetro] = useState<Rule | null>(null);
  const [removing, setRemoving] = useState<Rule | null>(null);

  const learned = state.rules.filter((r) => r.source === 'learned').length;
  const auto = state.txns.filter((t) => t.confidence >= 0.85).length;
  const autoPct = state.txns.length ? Math.round((auto / state.txns.length) * 100) : 0;

  const suggestions = useMemo(() => {
    const groups = new Map<string, { merchant: string; count: number; total: number; descriptions: string[] }>();
    for (const t of state.txns) {
      if (t.category !== 'other' || t.amount >= 0) continue;
      const key = t.merchant.toUpperCase();
      const cur = groups.get(key) ?? { merchant: t.merchant, count: 0, total: 0, descriptions: [] };
      cur.count += 1;
      cur.total += Math.abs(t.amount);
      cur.descriptions.push(t.description);
      groups.set(key, cur);
    }
    return [...groups.values()]
      .filter((g) => g.count >= 2)
      .sort((a, b) => b.count - a.count)
      .slice(0, 3);
  }, [state.txns]);

  return (
    <div className="page">
      <div className="page-head">
        <div>
          <div className="eyebrow">Learning loop</div>
          <h1 className="display">The model <em>learns from you.</em></h1>
          <p className="lede">
            Every correction can become a rule. Rules run before the built-in merchant list, so your judgement always
            wins. Apply one to the past whenever you want.
          </p>
        </div>
        <div className="head-actions">
          <button className="btn" onClick={() => navigateToCorrections()}>
            <Icon name="receipt" size={14} /> Correction log
          </button>
          <button className="btn btn-primary" onClick={() => setCreating(true)}>
            <Icon name="plus" size={14} /> New rule
          </button>
        </div>
      </div>

      <div className="grid">
        <div className="col-8 stack">
          <section className="panel">
            <div className="panel-head">
              <div>
                <h2 className="panel-title">Rules</h2>
                <p className="panel-sub">Higher priority wins when two rules match.</p>
              </div>
              <span className="badge">{state.rules.length} rules</span>
            </div>
            <div className="panel-body flush">
              {state.rules.length === 0 ? (
                <Empty
                  icon="split"
                  title="No rules yet"
                  body="Correct a category from the ledger and tick “learn a rule” — it will appear here."
                  action={<button className="btn btn-sm btn-primary" onClick={() => setCreating(true)}>Create one manually</button>}
                />
              ) : (
                <div className="table-wrap">
                  <table className="tbl">
                    <thead>
                      <tr>
                        <th>Pattern</th>
                        <th>Category</th>
                        <th className="hide-sm">Source</th>
                        <th className="hide-sm">Hits</th>
                        <th>Priority</th>
                        <th className="right">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {[...state.rules]
                        .sort((a, b) => b.priority - a.priority || b.createdAt - a.createdAt)
                        .map((r) => (
                          <tr key={r.id} style={{ opacity: r.enabled ? 1 : 0.55 }}>
                            <td>
                              <div className="mono small strong">{r.pattern}</div>
                              <div className="tiny" style={{ color: 'var(--muted)' }}>
                                {r.field} {r.matchType}
                              </div>
                            </td>
                            <td>
                              <span className="row" style={{ gap: 6 }}>
                                <span className="cat-dot" style={{ background: CATEGORY_MAP[r.category]?.color }} />
                                <span className="small">{CATEGORY_MAP[r.category]?.name}</span>
                              </span>
                            </td>
                            <td className="hide-sm">
                              <span className={`badge ${r.source === 'learned' ? 'info' : 'outline'}`}>{r.source}</span>
                            </td>
                            <td className="hide-sm num small">{r.hits}</td>
                            <td className="num small">{r.priority}</td>
                            <td>
                              <div className="row" style={{ gap: 2, justifyContent: 'flex-end' }}>
                                <div title={r.enabled ? 'Disable rule' : 'Enable rule'}>
                                  <Switch checked={r.enabled} label={`Toggle ${r.pattern}`} onChange={(v) => { updateRule(r.id, { enabled: v }); push(v ? 'Rule enabled' : 'Rule disabled'); }} />
                                </div>
                                <button className="btn btn-ghost btn-icon" title="Test this rule" aria-label={`Test ${r.pattern}`} onClick={() => setTesting(r)}>
                                  <Icon name="spark" size={13} />
                                </button>
                                <button className="btn btn-ghost btn-icon" title="Edit rule" aria-label={`Edit ${r.pattern}`} onClick={() => setEditing(r)}>
                                  <Icon name="pencil" size={13} />
                                </button>
                                <button className="btn btn-ghost btn-icon" title="Delete rule" aria-label={`Delete ${r.pattern}`} onClick={() => setRemoving(r)}>
                                  <Icon name="trash" size={13} />
                                </button>
                              </div>
                            </td>
                          </tr>
                        ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
            <div className="panel-foot">
              <span className="tiny" style={{ color: 'var(--muted)' }}>
                {learned} learned from corrections · {state.rules.filter((r) => r.source === 'manual').length} written by hand
              </span>
              <button className="linkish small" onClick={() => setCreating(true)}>Add a rule</button>
            </div>
          </section>

          <section className="panel">
            <div className="panel-head">
              <div>
                <h2 className="panel-title">Recent corrections</h2>
                <p className="panel-sub">The exact moments the model changed its mind.</p>
              </div>
            </div>
            <div className="panel-body flush">
              {state.corrections.length === 0 ? (
                <Empty icon="pencil" title="No corrections yet" body="When you fix a category in the ledger, the before-and-after is recorded here." />
              ) : (
                <div className="table-wrap">
                  <table className="tbl">
                    <thead>
                      <tr>
                        <th>Line</th>
                        <th>From</th>
                        <th>To</th>
                        <th className="hide-sm">Learned</th>
                        <th>When</th>
                      </tr>
                    </thead>
                    <tbody>
                      {state.corrections.slice(0, 8).map((c) => (
                        <tr key={c.id}>
                          <td className="small ellipsis" style={{ maxWidth: 300 }}>{c.description}</td>
                          <td className="small muted">{CM[c.from]?.name ?? c.from}</td>
                          <td className="small">{CM[c.to]?.name ?? c.to}</td>
                          <td className="hide-sm">{c.learnedRuleId ? <span className="badge info">Rule</span> : <span className="badge outline">Once</span>}</td>
                          <td className="tiny mono" style={{ color: 'var(--muted)' }}>
                            {new Date(c.at).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </section>
        </div>

        <aside className="col-4 stack">
          <section className="panel">
            <div className="panel-head">
              <div>
                <h2 className="panel-title">Learning health</h2>
                <p className="panel-sub">How much the model gets right unaided.</p>
              </div>
            </div>
            <div className="panel-body">
              <div className="big-number" style={{ fontSize: 42 }}>{autoPct}%</div>
              <p className="small muted" style={{ marginTop: 4 }}>of transactions were categorised with high confidence.</p>
              <div className="progress" style={{ marginTop: 10 }}>
                <span style={{ width: `${autoPct}%` }} />
              </div>
              <div className="divider dashed" />
              <div className="row-between small"><span className="muted">Needs a human</span><span className="num">{state.txns.filter((t) => t.category === 'other').length}</span></div>
              <div className="row-between small" style={{ marginTop: 4 }}><span className="muted">Rules learned</span><span className="num">{learned}</span></div>
              <div className="row-between small" style={{ marginTop: 4 }}><span className="muted">Corrections</span><span className="num">{state.corrections.length}</span></div>
              <div className="row-between small" style={{ marginTop: 4 }}><span className="muted">Rule hits</span><span className="num">{state.rules.reduce((s, r) => s + r.hits, 0)}</span></div>
            </div>
          </section>

          <section className="panel">
            <div className="panel-head">
              <div>
                <h2 className="panel-title">Merchants without a rule</h2>
                <p className="panel-sub">Repeated names still falling into Uncategorised.</p>
              </div>
            </div>
            <div className="panel-body" style={{ paddingTop: 4 }}>
              {suggestions.length === 0 && <p className="small muted">Nothing is waiting. The model has a home for every repeated merchant.</p>}
              {suggestions.map((s) => (
                <div className="goal-row" key={s.merchant}>
                  <div className="row-between">
                    <span className="small strong ellipsis" style={{ maxWidth: 170 }}>{s.merchant}</span>
                    <span className="tiny mono" style={{ color: 'var(--muted)' }}>{s.count} lines · {money(s.total)}</span>
                  </div>
                  <div className="row" style={{ marginTop: 6, gap: 6 }}>
                    <select
                      className="select select-sm"
                      style={{ width: 130 }}
                      id={`sugg-${s.merchant}`}
                      defaultValue="groceries"
                      aria-label={`Suggested category for ${s.merchant}`}
                    >
                      {CATEGORIES.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                    <button
                      className="btn btn-sm"
                      onClick={() => {
                        const el = document.getElementById(`sugg-${s.merchant}`) as HTMLSelectElement | null;
                        addRule({
                          pattern: s.merchant.toUpperCase().slice(0, 24),
                          field: 'description',
                          matchType: 'contains',
                          category: el?.value ?? 'groceries',
                          source: 'learned',
                          priority: 45,
                          enabled: true,
                          hits: s.count,
                        });
                        push(`Rule created for ${s.merchant}`);
                      }}
                    >
                      Create rule
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </section>

          <section className="panel">
            <div className="panel-head">
              <div>
                <h2 className="panel-title">How matching works</h2>
              </div>
            </div>
            <div className="panel-body">
              <p className="small muted">
                Rules run highest priority first. A rule can match the raw statement line or the cleaned merchant name,
                by contains, starts-with, exact text, or a regular expression.
              </p>
              <div className="note" style={{ marginTop: 10 }}>
                Corrections only change the future by default. Use <strong>Apply to past</strong> from a rule's test panel when you want history rewritten.
              </div>
            </div>
          </section>
        </aside>
      </div>

      {creating && (
        <RuleModal
          title="New rule"
          onClose={() => setCreating(false)}
          onSave={(r) => {
            addRule(r);
            push('Rule created');
            setCreating(false);
          }}
        />
      )}

      {editing && (
        <RuleModal
          title="Edit rule"
          initial={editing}
          onClose={() => setEditing(null)}
          onSave={(r) => {
            updateRule(editing.id, r);
            push('Rule updated');
            setEditing(null);
          }}
        />
      )}

      {testing && (
        <TestModal
          rule={testing}
          txns={state.txns}
          onClose={() => setTesting(null)}
          onRetro={() => { setRetro(testing); setTesting(null); }}
        />
      )}

      <Confirm
        open={!!retro}
        onClose={() => setRetro(null)}
        onConfirm={() => {
          if (!retro) return;
          const n = applyRuleRetro(retro.id);
          push(`Rule applied to ${n} past transaction${n === 1 ? '' : 's'}`);
        }}
        title="Apply this rule to past transactions?"
        body={`Every historical line matching “${retro?.pattern ?? ''}” will be recategorised to ${CATEGORY_MAP[retro?.category ?? 'other']?.name}. This cannot be undone.`}
        confirmLabel="Apply to past"
      />

      <Confirm
        open={!!removing}
        onClose={() => setRemoving(null)}
        onConfirm={() => {
          if (!removing) return;
          deleteRule(removing.id);
          push('Rule deleted');
        }}
        title="Delete this rule?"
        body="Transactions already filed by this rule keep their category. Future lines will fall back to the built-in classifier."
        confirmLabel="Delete rule"
        danger
      />
    </div>
  );
}

function navigateToCorrections() {
  const el = document.querySelector('.page .col-8 .panel:last-child');
  el?.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function RuleModal({
  title,
  initial,
  onClose,
  onSave,
}: {
  title: string;
  initial?: Rule;
  onClose: () => void;
  onSave: (r: Omit<Rule, 'id' | 'createdAt'>) => void;
}) {
  const [pattern, setPattern] = useState(initial?.pattern ?? '');
  const [field, setField] = useState<Rule['field']>(initial?.field ?? 'description');
  const [matchType, setMatchType] = useState<Rule['matchType']>(initial?.matchType ?? 'contains');
  const [category, setCategory] = useState(initial?.category ?? 'groceries');
  const [priority, setPriority] = useState(initial?.priority ?? 50);
  const [enabled, setEnabled] = useState(initial?.enabled ?? true);

  return (
    <Modal
      open
      onClose={onClose}
      title={title}
      sub="Rules run before the built-in merchant list."
      footer={
        <>
          <button className="btn" onClick={onClose}>Cancel</button>
          <button
            className="btn btn-primary"
            disabled={!pattern.trim()}
            onClick={() =>
              onSave({
                pattern: pattern.trim(),
                field,
                matchType,
                category,
                source: initial?.source ?? 'manual',
                priority,
                enabled,
                hits: initial?.hits ?? 0,
              })
            }
          >
            Save rule
          </button>
        </>
      }
    >
      <div className="stack-sm">
        <div className="field">
          <label htmlFor="rule-pattern">Match text</label>
          <input id="rule-pattern" className="input mono" placeholder="e.g. SWIGGY" value={pattern} onChange={(e) => setPattern(e.target.value)} />
        </div>
        <div className="form-row">
          <div className="field">
            <label>Field</label>
            <select className="select" value={field} onChange={(e) => setField(e.target.value as Rule['field'])}>
              <option value="description">Statement description</option>
              <option value="merchant">Cleaned merchant</option>
            </select>
          </div>
          <div className="field">
            <label>Match type</label>
            <select className="select" value={matchType} onChange={(e) => setMatchType(e.target.value as Rule['matchType'])}>
              <option value="contains">Contains</option>
              <option value="startsWith">Starts with</option>
              <option value="exact">Exact match</option>
              <option value="regex">Regular expression</option>
            </select>
          </div>
        </div>
        <div className="field">
          <label>Category</label>
          <select className="select" value={category} onChange={(e) => setCategory(e.target.value)}>
            {CATEGORIES.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        </div>
        <div className="form-row">
          <div className="field">
            <label>Priority (0–100)</label>
            <input className="input num" type="number" min={0} max={100} value={priority} onChange={(e) => setPriority(Number(e.target.value))} />
          </div>
          <div className="field">
            <label>Status</label>
            <div className="row" style={{ height: 32 }}>
              <Switch checked={enabled} onChange={setEnabled} label="Rule enabled" />
              <span className="small muted">{enabled ? 'Enabled' : 'Disabled'}</span>
            </div>
          </div>
        </div>
        {matchType === 'regex' && (
          <p className="tiny neg">Regular expressions are powerful and easy to get wrong. Test the rule before relying on it.</p>
        )}
      </div>
    </Modal>
  );
}

function TestModal({
  rule,
  txns,
  onClose,
  onRetro,
}: {
  rule: Rule;
  txns: { description: string; merchant: string }[];
  onClose: () => void;
  onRetro: () => void;
}) {
  const [sample, setSample] = useState('SWIGGY ORDER BANGALORE');
  const matches = txns.filter((t) => ruleMatches(rule, t)).length;
  const sampleMatches = ruleMatches(rule, { description: sample, merchant: sample });

  return (
    <Modal
      open
      onClose={onClose}
      title={`Test “${rule.pattern}”`}
      sub={`${rule.matchType} match on the ${rule.field}`}
      footer={
        <>
          <button className="btn" onClick={onClose}>Close</button>
          <button className="btn btn-primary" onClick={onRetro}>
            <Icon name="undo" size={13} /> Apply to {matches} past lines
          </button>
        </>
      }
    >
      <div className="stack-sm">
        <div className="field">
          <label htmlFor="test-sample">Try a statement line</label>
          <input id="test-sample" className="input mono" value={sample} onChange={(e) => setSample(e.target.value)} />
        </div>
        <div className={`callout ${sampleMatches ? 'note' : ''}`} style={{ borderColor: sampleMatches ? 'var(--accent)' : 'var(--line)' }}>
          <div className="row-between">
            <span className="small">{sampleMatches ? 'Matches this line' : 'Does not match'}</span>
            <span className={`badge ${sampleMatches ? 'pos' : 'outline'}`}>{sampleMatches ? CATEGORY_MAP[rule.category]?.name : 'No action'}</span>
          </div>
        </div>
        <div className="callout">
          <div className="row-between small">
            <span className="muted">Lines in your ledger that match</span>
            <span className="num">{matches}</span>
          </div>
        </div>
        <p className="tiny" style={{ color: 'var(--muted)' }}>
          Applying to the past rewrites categories for matching transactions. It does not create new transactions.
        </p>
      </div>
    </Modal>
  );
}

